"""JSON file storage with atomic writes and corruption handling.

Provides load/save of a dict-based data store to a JSON file.  Writes are
atomic (write-to-temp-then-rename) so that a crash mid-write never leaves a
corrupted file on disk.  If the file is corrupted, an empty default structure
is returned and the caller can decide whether to re-save.
"""

import json
import os
import tempfile
from pathlib import Path

DEFAULT_DATA = {"habits": [], "check_ins": []}


def _default_data() -> dict:
    """Return a fresh copy of the default data structure."""
    return {k: list(v) for k, v in DEFAULT_DATA.items()}


def load(path: str | Path) -> dict:
    """Load habit data from *path*.

    Returns a dict with keys ``habits`` and ``check_ins``.  If the file does
    not exist or is corrupted (invalid JSON), returns an empty default
    structure instead of raising.
    """
    path = Path(path)
    if not path.exists():
        return _default_data()

    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return _default_data()

    try:
        data = json.loads(text)
    except (json.JSONDecodeError, ValueError):
        # Corrupted file – return empty structure so the app can continue.
        return _default_data()

    if not isinstance(data, dict):
        return _default_data()

    # Ensure required keys exist with sensible defaults.
    data.setdefault("habits", [])
    data.setdefault("check_ins", [])
    return data


def save(path: str | Path, data: dict) -> None:
    """Atomically write *data* to *path* as JSON.

    Uses a temporary file in the same directory followed by ``os.replace`` so
    that a crash or power loss never leaves a half-written file.  The parent
    directory is created if it does not exist.
    """
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)

    # Write to a temp file in the same filesystem so os.replace is atomic.
    fd, tmp_path = tempfile.mkstemp(
        dir=str(path.parent), prefix=".habits_tmp_", suffix=".json"
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, path)
    except BaseException:
        # Clean up temp file on any error.
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

"""Check off a habit for today or a given date."""

from __future__ import annotations

import uuid
from datetime import date, datetime
from typing import Optional

import click

from habits.models import DATE_FORMAT, DEFAULT_HABIT_FILE
from habits.storage import load, save


def _find_habit(data: dict, habit_id_or_name: str) -> Optional[dict]:
    """Return the first active habit matching *habit_id_or_name* (by id or name)."""
    for h in data.get("habits", []):
        if not h.get("active", True):
            continue
        if h["id"] == habit_id_or_name or h["name"] == habit_id_or_name:
            return h
    return None


def _already_checked(data: dict, habit_id: str, check_date: date) -> bool:
    """Return True if a check-in already exists for *habit_id* on *check_date*."""
    for ci in data.get("check_ins", []):
        if ci["habit_id"] == habit_id and ci["date"] == check_date.strftime(DATE_FORMAT):
            return True
    return False


def _add_checkin(data: dict, habit_id: str, check_date: date) -> None:
    """Append a new CheckIn record to *data*."""
    data["check_ins"].append({
        "id": uuid.uuid4().hex,
        "habit_id": habit_id,
        "date": check_date.strftime(DATE_FORMAT),
        "timestamp": datetime.now().strftime("%Y-%m-%dT%H:%M:%S"),
    })


@click.command("checkoff")
@click.argument("HABIT", type=str)
@click.option(
    "-d",
    "--date",
    default=None,
    help="Date to check off (YYYY-MM-DD). Defaults to today.",
)
@click.option(
    "-f",
    "--data-file",
    type=click.Path(exists=True, readable=True),
    default=DEFAULT_HABIT_FILE,
    help=f"Path to the habits data file (default: {DEFAULT_HABIT_FILE}).",
)
def checkoff(habit: str, date: Optional[str], data_file: str) -> None:
    """Check off a habit for today or a given date.

    HABIT is either the habit ID or its name.  Future dates are rejected.
    If the habit is already checked off on that date, nothing happens (idempotent).
    """
    # Parse and validate the target date.
    if date is None:
        check_date = date.today()
    else:
        try:
            check_date = datetime.strptime(date, DATE_FORMAT).date()
        except ValueError:
            click.echo(f"Error: invalid date format '{date}'. Use YYYY-MM-DD.", err=True)
            raise SystemExit(1)

    if check_date > date.today():
        click.echo(f"Error: cannot check off a future date ({check_date}).", err=True)
        raise SystemExit(1)

    # Load data and find the habit.
    data = load(data_file)
    habit_record = _find_habit(data, habit)
    if habit_record is None:
        click.echo(f"Error: no active habit found matching '{habit}'.", err=True)
        raise SystemExit(1)

    # Idempotent guard.
    if _already_checked(data, habit_record["id"], check_date):
        click.echo(
            f"Already checked off '{habit_record['name']}' on {check_date.strftime(DATE_FORMAT)}.",
        )
        return

    # Add the check-in and persist.
    _add_checkin(data, habit_record["id"], check_date)
    save(data_file, data)
    click.echo(
        f"Checked off '{habit_record['name']}' on {check_date.strftime(DATE_FORMAT)}.",
    )

"""Undo a check-off for a given habit and date."""

from __future__ import annotations

from datetime import date, datetime
from typing import Optional

import click

from habits.models import DATE_FORMAT, DEFAULT_HABIT_FILE
from habits.storage import load, save


def _find_habit(data: dict, habit_id_or_name: str) -> Optional[dict]:
    """Return the first active habit matching *habit_id_or_name* (by id or name)."""
    for h in data.get("habits", []):
        if not h.get("active", True):
            continue
        if h["id"] == habit_id_or_name or h["name"] == habit_id_or_name:
            return h
    return None


def _remove_checkin(data: dict, habit_id: str, check_date_str: str) -> bool:
    """Remove the first matching check-in for *habit_id* on *check_date_str*.  Returns True if one was found."""
    before = len(data["check_ins"])
    data["check_ins"] = [
        ci
        for ci in data.get("check_ins", [])
        if not (ci["habit_id"] == habit_id and ci["date"] == check_date_str)
    ]
    return len(data["check_ins"]) < before


@click.command("undo")
@click.argument("HABIT", type=str)
@click.option(
    "-d",
    "--date",
    default=None,
    help="Date to undo (YYYY-MM-DD). Defaults to today.",
)
@click.option(
    "-f",
    "--data-file",
    type=click.Path(exists=True, readable=True),
    default=DEFAULT_HABIT_FILE,
    help=f"Path to the habits data file (default: {DEFAULT_HABIT_FILE}).",
)
def undo(habit: str, date: Optional[str], data_file: str) -> None:
    """Undo a check-off for HABIT on DATE.

    HABIT is either the habit ID or its name.  If no --date is given,
    today's check-in (if any) is removed.
    """
    # Parse and validate the target date.
    if date is None:
        check_date = date.today()
    else:
        try:
            check_date = datetime.strptime(date, DATE_FORMAT).date()
        except ValueError:
            click.echo(f"Error: invalid date format '{date}'. Use YYYY-MM-DD.", err=True)
            raise SystemExit(1)

    # Load data and find the habit.
    data = load(data_file)
    habit_record = _find_habit(data, habit)
    if habit_record is None:
        click.echo(f"Error: no active habit found matching '{habit}'.", err=True)
        raise SystemExit(1)

    check_date_str = check_date.strftime(DATE_FORMAT)

    # Remove the check-in.
    removed = _remove_checkin(data, habit_record["id"], check_date_str)
    if not removed:
        click.echo(
            f"No check-off found for '{habit_record['name']}' on {check_date_str} to undo.",
            err=True,
        )
        raise SystemExit(1)

    save(data_file, data)
    click.echo(f"Undid check-off for '{habit_record['name']}' on {check_date_str}.")
